import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx Scoring", () => {
  // Empty / no-sphinx armies
  it.todo("scores an empty army as 0");
  it.todo("scores an army of non-sphinx monsters as 0 — [hydra, zombie] is 0");

  // A single Sphinx, few types: the "else 1" branch
  it.todo("scores a lone sphinx as 1 — one type is not beyond three");
  it.todo("scores a sphinx with two types as 1 — [sphinx, hydra] is 1");
  it.todo("scores a sphinx with exactly three types as 1 — [sphinx, hydra, zombie] is 1");

  // The "2 per type beyond three" branch
  it.todo("scores a sphinx with four types as 2 — [sphinx, hydra, zombie, cyclops] is 2 (one type beyond three)");
  it.todo("scores a sphinx with five types as 4 — [sphinx, hydra, zombie, cyclops, orthrus] is 4 (two types beyond three)");
  it.todo("scores a sphinx with all seven monsters as 8 — four types beyond three");

  // Duplicates do not add types
  it.todo("counts each monster type once — [sphinx, hydra, hydra, zombie, zombie] is 1 (three types)");
  it.todo("counts duplicate sphinx cards as a single type — [sphinx, sphinx, hydra, zombie] is 1 each, total 2");

  // Undead Warrior rank variants are distinct types
  it.todo("treats undead warrior ranks as distinct types — [sphinx, undead-warrior r1, undead-warrior r2, undead-warrior r3] is 2 (four types)");
  it.todo("treats undead warriors of the same rank as one type — [sphinx, undead-warrior r2, undead-warrior r2] is 1 (two types)");

  // Multiple Sphinx cards each score
  it.todo("scores every sphinx in the army — [sphinx, sphinx] is 2 (two types, 1 each)");
  it.todo("scores two sphinxes with five types as 8 — 4 points each");

  // Full worked example
  it.todo("scores the spec example [sphinx, undead-warrior r2, hydra] as 1 — three types");
});

